const http = require('http');
const {Readable} = require('stream');
const request = require('./');

const server = http.createServer((req, res) => {
  if (req.url === '/response') {
    res.writeHead(200, {'content-type': 'text/plain'});
    res.write('ab');
    return setTimeout(() => res.end('cd'), 10);
  }
  req.resume();
  req.on('end', () => res.end('ok'));
});

server.listen(0, async () => {
  const base = `http://127.0.0.1:${server.address().port}`;
  const results = [];
  try {
    await new Promise((resolve, reject) => {
      const req = request.get(`${base}/response`).maxResponseSize(1);
      let count = 0;
      req.end((error) => {
        count++;
        try {
          if (!error || error.code !== 'ETOOLARGE' || count !== 1 || !req.hasSizeError()) throw new Error(`response: ${error && error.code}, count ${count}, size ${req.hasSizeError()}`);
          results.push('response');
          setTimeout(() => {
            if (count !== 1) reject(new Error('response callback repeated'));
            else resolve();
          }, 30);
        } catch (err) { reject(err); }
      });
    });

    for (const [name, makeRequest] of [
      ['string', () => request.post(`${base}/upload`).maxRequestSize(2).send('abc')],
      ['buffer', () => request.post(`${base}/upload`).maxRequestSize(2).send(Buffer.from('abc'))],
      ['multipart', () => request.post(`${base}/upload`).maxRequestSize(1).field('a', 'abc')]
    ]) {
      await new Promise((resolve, reject) => {
        const req = makeRequest();
        let count = 0;
        req.end((error) => {
          count++;
          try {
            if (!error || error.code !== 'ETOOLARGE' || count !== 1 || !req.hasSizeError()) throw new Error(`${name}: ${error && error.code}, count ${count}, size ${req.hasSizeError()}`);
            results.push(name);
            setTimeout(() => count === 1 ? resolve() : reject(new Error(`${name} callback repeated`)), 30);
          } catch (err) { reject(err); }
        });
      });
    }

    await new Promise((resolve, reject) => {
      const req = request.post(`${base}/upload`).maxRequestSize(2);
      let errors = 0;
      req.on('error', (error) => {
        errors++;
        if (error.code !== 'ETOOLARGE') reject(error);
      });
      req.on('abort', () => {
        setTimeout(() => {
          try {
            if (errors !== 1 || !req.hasSizeError()) throw new Error(`stream: errors ${errors}, size ${req.hasSizeError()}`);
            results.push('stream');
            resolve();
          } catch (err) { reject(err); }
        }, 20);
      });
      Readable.from(['ab', 'cd']).pipe(req);
    });

    console.log(results.join(','));
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    server.close();
  }
});
